bool IsThisPcLocation(const std::wstring& path) {
    return _wcsicmp(path.c_str(), kThisPcLocation) == 0;
}
bool IsRecycleBinLocation(const std::wstring& path) {
    return _wcsicmp(path.c_str(), kRecycleBinLocation) == 0;
}
bool UsesNamespaceFolderIdentity(const std::wstring& location) {
    return IsRecycleBinLocation(location) || location.starts_with(L"windhawk:pidl:");
}
// Provider names/parsing paths are not unique. This key is an opaque Shell
// identity, never a filesystem path or a command target. Commands keep PIDLs.
std::wstring NamespaceItemKey(PCIDLIST_ABSOLUTE pidl) {
    if (!pidl) return {};
    constexpr wchar_t digits[] = L"0123456789abcdef";
    const auto bytes = reinterpret_cast<const BYTE*>(pidl);
    const UINT size = ILGetSize(pidl);
    std::wstring key = L"windhawk:pidl:";
    key.reserve(key.size()+size*2);
    for (UINT i=0; i<size; ++i) {
        key.push_back(digits[bytes[i]>>4]); key.push_back(digits[bytes[i]&15]);
    }
    return key;
}
bool PidlBytesEqual(PCUIDLIST_RELATIVE first, PCUIDLIST_RELATIVE second) {
    if (!first || !second) return first == second;
    const UINT bytes = ILGetSize(first);
    return bytes == ILGetSize(second) && std::memcmp(first, second, bytes) == 0;
}
bool IsDriveRoot(const std::wstring& path) {
    return path.size() == 3 && path[1] == L':' &&
        (path[2] == L'\\' || path[2] == L'/');
}
