// DirectWrite layouts are device-independent. Keep shaping and trimming state
// across translated/faded frames, folder snapshots and D2D target recovery.
// Each tab owns its caches; the bound is an LRU, never a whole-cache flush.
struct SelectionShape {
    D2D1_RECT_F bounds{};
    // Grid labels display only a few lines. Keep translated paint/input
    // snapshots allocation-free, including keyboard/hover animation frames.
    std::array<D2D1_RECT_F,8> lines{};
    unsigned count = 0;
};
// Text coverage masks share A8 pages instead of one GPU texture per value.
// Shelves pack cells of one rounded height; every cell keeps a transparent
// gutter, so filtered sampling never reads a neighbor. Empty shelves split
// and merge, keeping pages usable across zoom-driven height changes.
struct GlyphAtlas {
    static constexpr UINT gutter = 1, shelfStep = 8;
    struct Shelf { UINT top = 0, height = 0; std::vector<std::pair<UINT,UINT>> free; }; // Sorted x, width.
    struct Page { ComPtr<ID2D1Bitmap1> bitmap; std::vector<Shelf> shelves; UINT used = 0; size_t live = 0; };
    UINT side = 0;
    std::vector<Page> pages;
    // Glyph positions are fractional; offsetting them by a cell origin can
    // move glyphs between subpixel buckets. Masks rasterize at the origin of
    // this surface, then copy into their cell bit-for-bit.
    ComPtr<ID2D1Bitmap1> scratch;
    unsigned long long serial = 0;
    size_t PageBytes() const { return size_t(side)*side; }
    bool Fits(UINT width, UINT height) const {
        return width && height && width<=side && (height+shelfStep-1)/shelfStep*shelfStep<=side;
    }
    bool Empty(const Shelf& shelf) const {
        return shelf.free.size()==1 && shelf.free.front().first==0 && shelf.free.front().second==side;
    }
    // CPU placement only; the caller creates a missing page's GPU surface.
    bool Place(Page& page, UINT width, UINT height, UINT& x, UINT& y) {
        if (!Fits(width,height)) return false;
        const UINT rounded = (height+shelfStep-1)/shelfStep*shelfStep;
        const auto take = [&](Shelf& shelf) {
            for (auto it=shelf.free.begin(); it!=shelf.free.end(); ++it) if (it->second>=width) {
                x=it->first; y=shelf.top; it->first+=width; it->second-=width;
                if (!it->second) shelf.free.erase(it);
                return true;
            }
            return false;
        };
        for (auto& shelf : page.shelves) if (shelf.height==rounded && take(shelf)) return true;
        Shelf* best = nullptr;
        for (auto& shelf : page.shelves)
            if (shelf.height>rounded && Empty(shelf) && (!best || shelf.height<best->height)) best=&shelf;
        if (best) {
            const size_t at = static_cast<size_t>(best-page.shelves.data());
            Shelf rest{best->top+rounded,best->height-rounded,{{0,side}}};
            best->height=rounded;
            page.shelves.insert(page.shelves.begin()+static_cast<std::ptrdiff_t>(at+1),std::move(rest));
            return take(page.shelves[at]);
        }
        if (page.used+rounded>side) return false;
        page.shelves.push_back({page.used,rounded,{{0,side}}});
        page.used+=rounded;
        return take(page.shelves.back());
    }
    void Release(size_t index, UINT x, UINT y, UINT width) {
        if (index>=pages.size()) return;
        auto& page = pages[index];
        const auto shelf = std::find_if(page.shelves.begin(),page.shelves.end(),[&](const Shelf& s) { return s.top==y; });
        if (shelf!=page.shelves.end()) {
            auto& free = shelf->free;
            auto it = free.insert(std::lower_bound(free.begin(),free.end(),std::pair<UINT,UINT>{x,0}),{x,width});
            if (it+1!=free.end() && it->first+it->second==(it+1)->first) { it->second+=(it+1)->second; free.erase(it+1); }
            if (it!=free.begin() && (it-1)->first+(it-1)->second==it->first) { (it-1)->second+=it->second; free.erase(it); }
            // Merge adjacent empty shelves; a trailing empty shelf returns its rows.
            for (size_t i=0; i+1<page.shelves.size();)
                if (Empty(page.shelves[i]) && Empty(page.shelves[i+1])) {
                    page.shelves[i].height+=page.shelves[i+1].height;
                    page.shelves.erase(page.shelves.begin()+static_cast<std::ptrdiff_t>(i+1));
                } else ++i;
            if (!page.shelves.empty() && Empty(page.shelves.back())) {
                page.used=page.shelves.back().top; page.shelves.pop_back();
            }
        }
        // No live cell remains, and retired masks are already drained: release
        // the page surface. A later mask recreates and clears it.
        if (page.live && !--page.live) { page.bitmap.Reset(); page.shelves.clear(); page.used=0; }
    }
};
// One reserved atlas cell. Its area returns only when the owning raster is
// destroyed: after paced retirement, never while a queued draw can read it.
class GlyphSlot {
    std::weak_ptr<GlyphAtlas> atlas;
    size_t page = 0;
    UINT x = 0, y = 0, width = 0, height = 0; // Outer cell including gutter.
    unsigned long long serial = 0;
public:
    GlyphSlot() = default;
    GlyphSlot(const std::shared_ptr<GlyphAtlas>& owner, size_t index, UINT left, UINT top, UINT w, UINT h)
        : atlas(owner), page(index), x(left), y(top), width(w), height(h), serial(++owner->serial) {}
    GlyphSlot(GlyphSlot&& other) noexcept { *this=std::move(other); }
    GlyphSlot& operator=(GlyphSlot&& other) noexcept {
        if (this!=&other) {
            Reset();
            atlas=std::move(other.atlas); page=other.page; x=other.x; y=other.y;
            width=std::exchange(other.width,0u); height=other.height; serial=other.serial;
        }
        return *this;
    }
    GlyphSlot(const GlyphSlot&) = delete;
    GlyphSlot& operator=(const GlyphSlot&) = delete;
    ~GlyphSlot() { Reset(); }
    explicit operator bool() const { return width!=0; }
    unsigned long long Serial() const { return serial; }
    size_t Page() const { return page; }
    D2D1_RECT_U Cell() const { return D2D1::RectU(x,y,x+width,y+height); }
    D2D1_RECT_F Source() const {
        const UINT g = GlyphAtlas::gutter;
        return D2D1::RectF(float(x+g),float(y+g),float(x+width-g),float(y+height-g));
    }
    D2D1_SIZE_U Size() const { return D2D1::SizeU(width-2*GlyphAtlas::gutter,height-2*GlyphAtlas::gutter); }
    void Reset() {
        if (!width) return;
        if (const auto owner=atlas.lock()) owner->Release(page,x,y,width);
        width=0; atlas.reset();
    }
};
struct TextLayoutCache {
    struct Raster {
        ComPtr<ID2D1Bitmap1> bitmap; // An atlas page when slot is set.
        GlyphSlot slot;
        // Stable identity of this mask's pixels, independent of page sharing.
        unsigned long long Identity() const {
            return slot ? slot.Serial() : static_cast<unsigned long long>(reinterpret_cast<uintptr_t>(bitmap.Get()));
        }
        unsigned long long rendering = 0;
        float width = 0.f, height = 0.f;
        float fontSize = 0.f; // Shaped size; zoom frames scale the mask from it.
        unsigned long long used = 0;
        size_t bytes = 0;
        unsigned long long painted = 0;
        bool underline = false;
        // Grayscale text alpha correction depends on the brush luminance: a mask
        // rasterized for white text is not the coverage DirectWrite gives dark text.
        unsigned color = 0xFFFFFF;
    };
    struct Layout {
        ComPtr<IDWriteTextLayout> text;
        float width = 0.f, height = 0.f;
        std::list<const std::wstring*>::iterator recent;
        unsigned long long used = 0;    // Tab-wide recency, comparable across the four caches.
        unsigned long long painted = 0; // Paint serial that last drew it; 0 for measurement only.
        float naturalWidth = -1.f; // Intrinsic measurement survives viewport geometry changes.
        std::vector<Raster> rasters;
        size_t rasterBytes = 0;
        bool displayed = false; // Direct drawing is ready content too, independent of mask geometry.
        unsigned long long generation = 0; // Shape lazily for the cache's current font/alignment.
        SelectionShape filenameSelection;
        bool filenameSelectionReady = false;
        bool middleTrim = false;
    };
    ComPtr<IDWriteTextFormat> format;
    DWRITE_TEXT_ALIGNMENT alignment = DWRITE_TEXT_ALIGNMENT_LEADING;
    // LRU order refers to the map's own keys (stable node storage); erasing a
    // layout always unlinks its node first, so no entry outlives its key.
    std::list<const std::wstring*> recent;
    std::unordered_map<std::wstring, Layout> layouts;
    size_t rasterBytes = 0;
    unsigned long long generation = 0;
    unsigned long long faceSerial = 0;
};
struct GroupHeaderMotion {
    int sectionIndex = -1;
    float oldTop = 0.f;
    bool entering = false;
    float oldHeight = -1.f, oldOpacity = 1.f;
};

// Explorer's Show hidden items and Hide protected OS files are different
// settings. Capture a tiny immutable policy on the owning UI thread; workers
// never query Shell settings, and all icon/index/row paths see the same rows.
struct ShellVisibilityPolicy {
    bool showHidden = false;
    bool showProtected = false;
    bool operator==(const ShellVisibilityPolicy& other) const {
        return showHidden == other.showHidden &&
               showProtected == other.showProtected;
    }
    bool operator!=(const ShellVisibilityPolicy& other) const {
        return !(*this == other);
    }
};

ShellVisibilityPolicy ReadShellVisibilityPolicy() {
    SHELLSTATE settings{};
    SHGetSetSettings(&settings, SSF_SHOWALLOBJECTS |
        SSF_SHOWSUPERHIDDEN, FALSE);
    return {settings.fShowAllObjects != 0, settings.fShowSuperHidden != 0};
}

struct ShellClickPolicy {
    bool singleClick = false;
    bool underlineHot = false, underlineCold = false;
    bool checkSelect = false;
    bool itemTips = true; // Folder Options: "Show pop-up description for folder and desktop items".
};
ShellClickPolicy ReadShellClickPolicy() {
    SHELLSTATE settings{}; settings.fDoubleClickInWebView = -1;
    SHGetSetSettings(&settings,SSF_DOUBLECLICKINWEBVIEW | SSF_AUTOCHECKSELECT | SSF_SHOWINFOTIP,FALSE);
    ShellClickPolicy policy;
    policy.itemTips = settings.fShowInfoTip != 0;
    policy.checkSelect = settings.fAutoCheckSelect != 0;
    policy.singleClick = !settings.fDoubleClickInWebView;
    if (!policy.singleClick) return policy;
    DWORD mode = 2, bytes = sizeof(mode);
    // Explorer's IconUnderline modes: 0=always, 1=never, 2=hot,
    // 3=browser. Read Shell's user/machine fallback without writing it.
    if (SHRegGetUSValueW(L"Software\\Microsoft\\Windows\\CurrentVersion\\Explorer",
        L"IconUnderline",nullptr,&mode,&bytes,FALSE,nullptr,0)!=ERROR_SUCCESS || bytes!=sizeof(mode) || mode>3) mode=2;
    if (mode == 3) {
        wchar_t browser[16] = L"yes"; bytes = sizeof(browser);
        if (SHRegGetUSValueW(L"Software\\Microsoft\\Internet Explorer\\Main",
            L"Anchor Underline",nullptr,browser,&bytes,FALSE,nullptr,0)!=ERROR_SUCCESS)
            wcscpy_s(browser,L"yes");
        browser[ARRAYSIZE(browser)-1] = 0;
        mode = _wcsicmp(browser,L"no")==0 ? 1 : _wcsicmp(browser,L"hover")==0 ? 2 : 0;
    }
    policy.underlineHot = mode == 0 || mode == 2;
    policy.underlineCold = mode == 0;
    return policy;
}

// Exclude protected HIDDEN+SYSTEM entries even when ordinary hidden items
// are displayed; this includes Explorer's normally suppressed desktop.ini.
// A protected-file override does not implicitly turn on ordinary hidden items.
// SYSTEM alone is not protected: CFSFolder lists it (customized folders and
// cloud drive roots commonly carry READONLY|SYSTEM).
bool ShellItemVisible(DWORD attributes, const ShellVisibilityPolicy& policy,
                      const wchar_t* name) {
    // Office owner/lock files are implementation details, not selectable
    // documents. Filter before publishing names/indices, even if hidden items
    // are shown or Office has not applied the hidden attribute yet. Keep
    // similarly named folders and ordinary temporary/hidden files intact.
    if (!(attributes & FILE_ATTRIBUTE_DIRECTORY) && name &&
        name[0] == L'~' && name[1] == L'$') return false;
    const bool hidden = (attributes & FILE_ATTRIBUTE_HIDDEN) != 0;
    const bool system = (attributes & FILE_ATTRIBUTE_SYSTEM) != 0;
    // Explorer's protected-files option and ordinary hidden-files option
    // are independent: both must permit an item marked HIDDEN | SYSTEM.
    if (hidden && !policy.showHidden) return false;
    if (hidden && system && !policy.showProtected) return false;
    return true;
}

SHCONTF ShellEnumerationFlags(const ShellVisibilityPolicy& policy) {
    SHCONTF flags = SHCONTF_FOLDERS | SHCONTF_NONFOLDERS;
    if (policy.showHidden) flags |= SHCONTF_INCLUDEHIDDEN;
    if (policy.showProtected) flags |= SHCONTF_INCLUDESUPERHIDDEN;
    return flags;
}

// One RAM-only per-tab directory cache, indexed by filesystem path. A snapshot
// owns the *same vector* that the GPU previously displayed: on a hit we move it
// back rather than copying or rebuilding thousands of filenames on Explorer's
// UI thread. The byte budget, not navigation depth, controls eviction.
// Built only by the directory worker. Each element contains a folded
// full-path hash and the entry's actual GPU row index. The small vector avoids
// maintaining 100k duplicated path strings, and lookup is O(log rows).
// Hash collisions are resolved against the original full path before use.
using EntryPathIndex = std::vector<std::pair<size_t, int>>;
// Sparse local identity changes between worker-built directory snapshots.
// Updating one row must not rebuild/shift the whole sorted index on the STA.
using EntryPathUpdates = std::map<size_t, std::set<int>>;
size_t ContinueSelectionPathHash(size_t hash, std::wstring_view path) noexcept {
    for (wchar_t ch : path) {
        hash ^= static_cast<size_t>(towlower(ch));
        hash *= static_cast<size_t>(16777619u);
    }
    return hash;
}
size_t SelectionPathHash(const std::wstring& path) noexcept {
    return ContinueSelectionPathHash(static_cast<size_t>(2166136261u),path);
}

struct CaseInsensitiveFolderLess {
    bool operator()(const std::wstring& a, const std::wstring& b) const {
        return _wcsicmp(a.c_str(), b.c_str()) < 0;
    }
};

// Resolved properties belong to a file, not a row or sort generation. The
// owning UI thread fills this cache incrementally from accepted completions;
// new snapshots hydrate only their visible rows, before requesting providers.
struct RowDetailsCache {
    RowDetailsCache() = default;
    RowDetailsCache(RowDetailsCache&&) = default;
    RowDetailsCache& operator=(RowDetailsCache&&) = default;
    RowDetailsCache(const RowDetailsCache&) = delete;
    RowDetailsCache& operator=(const RowDetailsCache&) = delete;
    struct Record {
        Entry value;
        size_t bytes = 0;
        std::list<const std::wstring*>::iterator recent;
    };
    std::list<const std::wstring*> recent; // The map's own keys; Erase unlinks first.
    std::map<std::wstring, Record, CaseInsensitiveFolderLess> entries;
    size_t usedBytes = 0;
    bool empty() const { return entries.empty(); }
    void Erase(const std::wstring& path) {
        const auto it = entries.find(path);
        if (it == entries.end()) return;
        usedBytes -= it->second.bytes;
        recent.erase(it->second.recent);
        entries.erase(it);
    }
};

struct FolderViewMode {
    UINT mode = 0; // No native baseline: an explicit View command.
    int iconSize = 0;
};
struct FolderChangeStamp {
    HANDLE change = INVALID_HANDLE_VALUE;
    std::atomic<LONGLONG> observedQpc{0};
    unsigned long long revision = 0; // Owner STA only; worker never reads it.
    ~FolderChangeStamp() {
        if (change != INVALID_HANDLE_VALUE) FindCloseChangeNotification(change);
    }
};
struct CachedFolderSnapshot {
    std::shared_ptr<const std::vector<Entry>> presentationEntries;
    SharedPidl folderIdentity;
    std::wstring path;
    SortSpec sort;
    ShellVisibilityPolicy visibility;
    ShellGroupSpec grouping;
    FolderViewMode viewMode;
    std::vector<Entry> entries;
    EntryPathIndex pathIndex;
    EntryPathUpdates pathUpdates;
    std::shared_ptr<const NamespaceIdentities> namespaceIdentities;
    RowDetailsCache details;
    unsigned long long orderHash = 0;
    unsigned long long metadataHash = 0;
    size_t estimatedBytes = 0;
    ULONGLONG lastUse = 0;
    std::weak_ptr<FolderChangeStamp> changeStamp; // History never owns a directory watch.
    unsigned long long changeRevision = 0;
};

struct FolderCache {
    using TabFolders = std::map<std::wstring, CachedFolderSnapshot,
                                CaseInsensitiveFolderLess>;
    TabFolders folders;
    size_t usedBytes = 0;
    size_t snapshotCount = 0;
    size_t budgetBytes = 0;
    ULONGLONG accessSequence = 0;
};

// Shell lookups AND WIC/HICON conversion run on a tab-owned Shell worker.
// Only bounded premultiplied BGRA buffers cross onto the Explorer UI thread;
// that thread owns the Direct2D bitmaps and never decodes an HICON.
// Published pixels are shared by immutable presentation snapshots. Producers
// detach on mutation; taking a new frame never copies a thumbnail's bytes.
class PixelBytes {
    std::shared_ptr<std::vector<BYTE>> bytes;
    void Write() {
        if (!bytes) bytes=std::make_shared<std::vector<BYTE>>();
        else if (bytes.use_count()!=1) bytes=std::make_shared<std::vector<BYTE>>(*bytes);
    }
    static const std::vector<BYTE>& Empty() { static const std::vector<BYTE> value; return value; }
public:
    PixelBytes()=default;
    PixelBytes(std::vector<BYTE> value) : bytes(std::make_shared<std::vector<BYTE>>(std::move(value))) {}
    PixelBytes& operator=(std::vector<BYTE> value) { bytes=std::make_shared<std::vector<BYTE>>(std::move(value)); return *this; }
    bool empty() const { return !bytes || bytes->empty(); }
    size_t size() const { return bytes ? bytes->size() : 0; }
    size_t capacity() const { return bytes ? bytes->capacity() : 0; }
    const void* Identity() const { return bytes.get(); }
    const BYTE* data() const { return bytes ? bytes->data() : nullptr; }
    BYTE* data() { Write(); return bytes->data(); }
    void resize(size_t n) { Write(); bytes->resize(n); }
    void assign(size_t n,BYTE value) { bytes=std::make_shared<std::vector<BYTE>>(n,value); }
    template<class It> void assign(It first,It last) { bytes=std::make_shared<std::vector<BYTE>>(first,last); }
    void clear() { bytes.reset(); }
    BYTE& operator[](size_t n) { Write(); return (*bytes)[n]; }
    const BYTE& operator[](size_t n) const { return (*bytes)[n]; }
    auto begin() { Write(); return bytes->begin(); }
    auto end() { Write(); return bytes->end(); }
    auto begin() const { return bytes ? bytes->cbegin() : Empty().cbegin(); }
    auto end() const { return bytes ? bytes->cend() : Empty().cend(); }
};
struct IconPixels {
    UINT width = 0, height = 0, stride = 0;
    PixelBytes data;
    // Real thumbnail + optional badge share ONE texture/upload/cache record.
    // The badge occupies a separate atlas band, never the provider's pixels.
    // Zero dimensions retain the ordinary icon path, including fallbacks.
    UINT thumbnailWidth = 0, thumbnailHeight = 0, badgeSize = 0;
    // Visible fraction of a Shell overlay's full canvas, measured on its worker.
    float overlayExtent = 1.f;
    bool Ready() const {
        return width && height && width <= UINT_MAX/4 && stride >= width*4 &&
            data.size()/stride >= height;
    }
};
struct ThumbnailStyle {
    bool filmstrip = false;
    IconPixels badge;
};
struct IconRecord {
    IconPixels pixels;
    IconPixels bitmapPixels; // Geometry/bytes belonging to the accepted GPU texture.
    ComPtr<ID2D1Bitmap> bitmap;
    bool pending = false;
    // Distinguish an in-flight job from the same path on a previous visit.
    unsigned long long pendingToken = 0;
    // Unique per request even when a file's Shell icon changes in place.
    unsigned long long pendingRequestId = 0;
    bool bitmapAttempted = false;
    ULONGLONG used = 0;
    ULONGLONG visibleGeneration = 0;
    unsigned long long painted = 0;
    bool association = false;
    bool resolved = false; // Includes a failed lookup; cancelled queued work is not resolved.
    bool needsRefresh = false; // Invalidated artwork remains a fallback until replacement succeeds.
    unsigned failures = 0;
    size_t cacheBytes = 0;
    UINT requestedSize = 32;
    bool sourceLimited = false;
    // An overlay query record holds no pixels, only the item's Shell overlay
    // as a system image-list index (-1: none); its artwork is shared.
    bool overlayQuery = false;
    int overlayImage = -1;
    bool presentationListed=false;
    std::list<const std::wstring*>::iterator presentationRecent;
    IconRecord() = default;
    IconRecord(const IconRecord&) = delete;
    IconRecord& operator=(const IconRecord&) = delete;
    IconRecord(IconRecord&&) = default;
    IconRecord& operator=(IconRecord&&) = default;
};
// Immutable, bounded foreground packet. PixelBytes shares the existing decoded
