    LOGFONTW presentationFont{};
    float presentationDocumentHeight=0.f, presentationGroupOrigin=0.f;
    bool presentationActive=true;
    std::shared_ptr<const PresentationItems> presentationItems;
    std::unordered_map<int,PresentationRowCache> presentationRows; // Owner capture reuse only.
    std::unordered_map<std::wstring,int> presentationGroups;
    std::vector<int> presentationSectionIndices;
    std::list<const std::wstring*> presentationIconRecent; // icons' own keys; every erase unlinks first.
    bool presentationCachePending=false;
    size_t presentationImageWorkingBytes=0;
    std::shared_ptr<const std::vector<Entry>> presentationEntries;
    std::wstring presentationModelFolder;
    ShellGroupSpec presentationModelGrouping;
    unsigned long long presentationOrderHash=0;
    ViewState* deferredDisposeNext=nullptr; // Owner-thread intrusive retirement queue.
    bool disposalQueued=false;
    std::shared_ptr<TabBackground> background = std::make_shared<TabBackground>();
    HWND hwnd = nullptr;
    HWND nativeHwnd = nullptr;
    HWND frameHwnd = nullptr; // Explorer frame owns this tab's distinct overlay HWND.
    HWND viewToggle = nullptr, viewToggleTooltip = nullptr;
    HICON viewToggleIcons[2]{}; // Normal/disabled, premultiplied BGRA with alpha.
    int viewToggleIconPx = 0;
    COLORREF viewToggleIconColor = CLR_INVALID;
    HWND viewToggleNeighbor = nullptr;
    StatusButtonSnapshot viewToggleGeometry;
    StatusButtonQuery viewToggleQuery;
    unsigned long long viewToggleGeometryToken=0;
    bool viewToggleGeometryPending=false;
    bool viewToggleNeighborSearched = false, viewToggleBufferedPaint = false;
    int viewToggleDpi = 0;
    bool viewToggleLayoutQueued = false;
    bool viewToggleHot = false, viewTogglePaletteDirty = true;
    COLORREF viewToggleBackground = CLR_INVALID, viewToggleForeground = CLR_INVALID;
    void ReleaseViewToggle() {
        for (HWND child : {viewToggleTooltip, viewToggle}) {
            if (IsWindow(child) && GetPropW(child, kViewToggleOwnerProperty) == hwnd) {
                if (child==viewToggle)
                    RemoveWindowSubclass(child,ViewToggleSubclass,reinterpret_cast<UINT_PTR>(ViewToggleSubclass));
                RemovePropW(child,kViewToggleOwnerProperty);
                DestroyWindow(child);
            }
        }
        for (HICON icon : viewToggleIcons) if (icon) DestroyIcon(icon);
        if (viewToggleBufferedPaint) BufferedPaintUnInit();
        viewToggleTooltip = viewToggle = nullptr;
        viewToggleNeighbor = nullptr;
        viewToggleGeometry={}; viewToggleQuery={};
        viewToggleGeometryToken=0; viewToggleGeometryPending=false;
        viewToggleNeighborSearched = viewToggleBufferedPaint = false;
        viewToggleIcons[0] = viewToggleIcons[1] = nullptr;
        viewToggleIconPx = 0;
        viewToggleIconColor = CLR_INVALID;
        viewToggleDpi = 0;
        viewToggleHot = false;
        viewTogglePaletteDirty = true;
    }
    ViewState() {background->notificationLifetime=lifetimeToken;}
    ~ViewState() {
        ReleaseViewToggle();
        if (frameLatencyWaitable) CloseHandle(frameLatencyWaitable);
    }
    bool rtlLayout = false; // Follow Shell UI direction, not filename script.
    float paintWidth = 0.f; // Cached paint width for inexpensive logical->visual mapping.
    bool inScope = true;
    // This PC owns a Shell namespace model. Immutable PIDLs, rather than
    // hidden native row indices, identify its rows and navigation requests.
    bool thisPcGpu = false;
    bool thisPcRowsDirty = true;
    unsigned thisPcSnapshotRetries = 0; // Diagnostic attempts, never a readiness limit.
    bool nativeRowsMessageQueued = false;
    bool nativeRowsNeedCapture = true;
    bool nativeRowsPending = false;
    bool nativeRowsComplete = false;
    unsigned long long nativeRowsToken = 0;
    unsigned long long nativeRowsViewToken = 0;
    std::vector<Entry> nativeRows; // Provider-resolved identities; projection never reopens Shell items.
    bool initialModePending = false;
    bool overlayInitializing = false;
    bool nativePresentationPending = false;
    bool nativeModeSignalQueued = false, nativeModeApplying = false;
    bool nativeModeHintPending = false, nativeSettingsHintPending = false;
    bool nativeViewCommandPending = false, nativeColumnsDirty = true;
    bool nativeMenuCommandPending = false;
    ULONGLONG lastInteractionTick = 0;
    LPARAM lastPointerInput = -1;
    std::vector<DriveCapacity> thisPcCapacities;
    // Shell item identities already submitted for a capacity probe. Do not
    // repeat work on grouping/column changes or a redundant WinEvent.
    std::vector<std::wstring> thisPcSpaceRequestedPaths;
    ULONGLONG driveCapacityRequestedAt = 0;
    unsigned long long capacityToken = 0;
    bool driveSpaceRefreshPending = false;
    ULONGLONG driveSpaceChangedAt = 0;
    bool detailsViewActive = true; // Legacy name: gate for every supported GPU view mode.
    bool columnsView = true; // Details=true, List=false.
    bool gridView = false;
    int nativeIconSize = 48;
    UINT layoutNativeMode = FVM_DETAILS;
    int layoutIconSize = 0;
    int itemsPerRow = 1;
    float itemWidth = 0.f;
    ComPtr<IColumnManager> columnManager;
    std::vector<ExplorerColumn> columns;
    // RAM-only column dimensions for this tab. Directory snapshots do not own them.
    std::unordered_map<HWND, TabPresentation> tabPresentations;
    // Available keys are captured on the owning STA; localized labels resolve
    // independently of names, icons and slow volume/property providers.
    ColumnChoices columnMenuChoices;
    unsigned long long columnCatalogToken = 0;
    bool columnCatalogPending = false, columnCatalogReady = false;
    bool columnMenuPending = false;
    POINT columnMenuPoint{};
    // Changes to native column widths must run on Explorer's STA. Defer the
    // minimal custom-only restores until the system has been idle; never block
    // the user's click-to-header-paint path with SetColumnInfo loops.
    std::vector<PendingColumnWidth> pendingColumnWidths;
    HWND pendingWidthNativeHwnd = nullptr;
    ULONGLONG pendingWidthEarliest = 0;
    unsigned long long columnEpoch = 1;
    unsigned long long propertyEpoch = 1;
    unsigned long long detailsRefreshEpoch = 0;
    ULONGLONG lastColumnsProbe = 0;
    float columnContentWidth = 0.f, horizontalScroll = 0.f;
    bool horizontalScrollbarAdmitted = false; // Optional chrome waits for settled column geometry.
    bool horizontalScrollbarPublished = false; // A presented frame has shown the admitted bar.
    // First model sequence of the current admission run. A receipt reaching
    // it proves the lane drew the bar; capture alone does not (newer models
    // can supersede a captured one before it is drawn).
    unsigned long long horizontalScrollbarAdmittedSequence = 0;
    bool columnVerticalBarVisible = false; // Last layout's scrollbar clearance.
    bool columnTransitionActive = false;
    bool columnTransitionSpring = false;
    bool columnModeTransition = false;
    bool columnPresentationPending = false; // Settled geometry must be accepted by rendering.
    LONGLONG rejectedColumnComposition = 0; // Do not repeat a failed allocation every frame.
    SIZE rejectedColumnCompositionSize{};
    bool columnModeEntrancePending = false;
    float columnHeaderFrom = 0.f, columnHeaderTo = 0.f;
    LARGE_INTEGER columnTransitionStartedQpc{};
    std::vector<ColumnMotion> columnMotion;
    std::vector<ExplorerColumn> disappearingColumns; // Paint-only, on the same column clock.
    // The pressed header is only armed until the OS drag threshold is crossed.
    // Preview order is GPU-only; native Shell columns change exactly once on drop.
    bool columnDragArmed = false;
    bool columnDragActive = false;
    PROPERTYKEY columnDragKey{};
    int columnDragSource = -1;
    int columnDragDestination = -1;
    int columnDragDownX = 0, columnDragDownY = 0;
    float columnDragPointerX = 0.f; // document-logical X (includes horizontal scroll)
