bool AttachShellSelectionEvents(ViewState& state, IDispatch* browser);
void RetryShellSubscriptions(ViewState& state, ULONGLONG now);
bool ShellRowsInteractive(const ViewState& state) {
    return state.loaded && !state.namesPreview; // Background refresh cannot invalidate owned PIDLs.
}

constexpr unsigned kOverlayFeatureSteps = 5;
void InitializeFrameShellEvents(ViewState& state);
void PrepareInitialOverlay(ViewState& state);
unsigned SystemStyleChangeMask(UINT message, WPARAM action, LPARAM area);
void QueueStyleChange(ViewState& state, unsigned changes);
