    case WM_MOUSEHWHEEL:
        if (s) DiscardCompletedMouseClick(*s);
        if (s && s->columnsView) {
            const float change = static_cast<float>(GET_WHEEL_DELTA_WPARAM(wParam)) /
                WHEEL_DELTA * Scale96(54, DpiOf(hwnd));
            SetHorizontalScroll(*s, s->horizontalScroll +
                (s->rtlLayout ? -change : change));
        }
        return 0;
    case WM_MOUSEWHEEL:
        if (s) {
            DiscardCompletedMouseClick(*s);
            // Some drivers emit a synthetic Ctrl+wheel while DM owns a pinch.
            // Do not apply the same zoom twice.
            if ((s->manipulationFrameActive && s->touchpadPinching) ||
                (s->touch.active && s->touchpadPinching)) return 0;
            const short delta = GET_WHEEL_DELTA_WPARAM(wParam);
            if ((GetKeyState(VK_SHIFT) & 0x8000) && s->columnsView) {
                SetHorizontalScroll(*s, s->horizontalScroll -
                    static_cast<float>(delta) / WHEEL_DELTA *
                    Scale96(54, DpiOf(hwnd)));
                return 0;
            }
            if ((GET_KEYSTATE_WPARAM(wParam) & MK_CONTROL) ||
                (GetKeyState(VK_CONTROL) & 0x8000)) {
                // Keep selection visible while changing row height and font size.
                s->wheelRemainder += delta;
                const int steps = s->wheelRemainder / WHEEL_DELTA;
                s->wheelRemainder -= steps * WHEEL_DELTA;
                if (steps) {
                    const int old96 = s->rowHeight96[s->gridView] ?
                        s->rowHeight96[s->gridView] : g_row96.load();
                    ApplyRowHeight(*s, static_cast<double>(old96) + steps * 2);
                } else if (delta) ScheduleZoomAutoRefit(*s, false);
            } else {
                AdvanceRowHeight(*s, true);
                const UINT lines = g_wheelLines.load(std::memory_order_relaxed);
                const float unit = lines == WHEEL_PAGESCROLL
                    ? static_cast<float>(ViewHeight(*s))
                    : static_cast<float>(std::min(lines, 20u)) * s->rowPx;
                // Standard Win32 wheel support remains. This path does not
                // attempt to intercept precision touchpad gestures handled by
                // Explorer or its compositor.
                const float pixels = static_cast<float>(delta) /
                    static_cast<float>(WHEEL_DELTA) * unit;
                MoveScroll(*s, s->scrollTarget - pixels);
                QueueVisibleDataFrame(*s);
                Redraw(*s);
            }
        }
