                const int index = RowFromPoint(*s, y, x);
                const bool control = (GetKeyState(VK_CONTROL) & 0x8000) != 0;
                const bool shift = (GetKeyState(VK_SHIFT) & 0x8000) != 0;
                s->mousePressControl = control;
                s->mousePressShift = shift;
